1	package com.example.starter.evidence;
2	
3	import org.springframework.jdbc.core.JdbcTemplate;
4	import org.springframework.jdbc.core.RowMapper;
5	import org.springframework.stereotype.Repository;
6	
7	import java.sql.ResultSet;
8	import java.sql.SQLException;
9	import java.time.LocalDateTime;
10	import java.util.List;
11	import java.util.Optional;
12	
13	/**
14	 * 证物表访问。状态与保管人变更必须先通过 {@link #findByKeyForUpdate} 锁定证物行，
15	 * 保证并发交接/取消/核验按事务提交顺序生效。
16	 */
17	@Repository
18	public class EvidenceRepository {
19	
20	    private static final EvidenceRowMapper ROW_MAPPER = new EvidenceRowMapper();
21	
22	    private final JdbcTemplate jdbc;
23	
24	    public EvidenceRepository(JdbcTemplate jdbc) {
25	        this.jdbc = jdbc;
26	    }
27	
28	    /**
29	     * 插入新证物，初始状态 SEALED，保管人为入库操作人。
30	     */
31	    public void insert(String evidenceKey, String caseKey, String category, String sealNo,
32	                       String custodianId, LocalDateTime now) {
33	        jdbc.update("""
34	                        INSERT INTO evidence
35	                            (evidence_key, case_key, category, seal_no, custodian_id, status, created_at, updated_at)
36	                        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
37	                        """,
38	                evidenceKey, caseKey, category, sealNo, custodianId,
