    private List<String> stock(String source, String target, int n) {
        location(source);
        location(target);
        List<String> keys = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String key = intake("alice");
            shelve("alice", key, source);
            keys.add(key);
